import Image from "next/image";
import { cn } from "@balm/ui";
import { COMPANY } from "@/lib/company";

/**
 * BALM brand logo: the bridge, tree and truck mark with the "Bay Area
 * Landscaping Materials" wordmark, from the 8K masters in /public/brand.
 *   - tone="brand"    → full-colour horizontal lockup, for light backgrounds
 *   - tone="inverted" → white line-art stacked lockup, for dark backgrounds
 *
 * The webp files are generated by scripts/build-brand.mjs. The wordmark is
 * part of the artwork.
 */

type LogoProps = {
  tone?: "brand" | "inverted";
  /** rendered height in px (width scales by intrinsic aspect ratio) */
  height?: number;
  priority?: boolean;
  className?: string;
};

const ART = {
  brand: { src: "/brand/logo-horizontal.webp", w: 687, h: 160 },
  inverted: { src: "/brand/logo-white.webp", w: 625, h: 480 },
} as const;

export function Logo({
  tone = "brand",
  height = 56,
  priority = false,
  className,
}: LogoProps) {
  const art = ART[tone];
  const width = Math.round((art.w / art.h) * height);

  return (
    <Image
      src={art.src}
      alt={COMPANY.legalName}
      width={width}
      height={height}
      priority={priority}
      sizes={`${width}px`}
      className={cn("h-auto w-auto object-contain", className)}
      style={{ height, width: "auto" }}
    />
  );
}
